// Optional: a thin modern-C++ layer over the generated C header.
// It turns "remember to call free" into RAII so you can't leak.
#pragma once
#include <rustcore.h>   // generated by cbindgen from rust/src/lib.rs

#include <memory>
#include <string>
#include <vector>

namespace rs {

inline int add(int a, int b) { return rs_add(a, b); }

inline double sum(const std::vector<double>& v) { return rs_sum(v.data(), v.size()); }

inline std::string greet(const std::string& name) {
    char* raw = rs_greet(name.c_str());
    std::string out(raw);
    rs_string_free(raw);            // Rust allocated it, so Rust frees it
    return out;
}

// Owns a Rust Counter; destructor calls counter_free automatically.
class Counter {
public:
    explicit Counter(long long start = 0) : p_(counter_new(start)) {}
    long long increment() { return counter_increment(p_.get()); }
private:
    struct Deleter { void operator()(::Counter* c) const { counter_free(c); } };
    std::unique_ptr<::Counter, Deleter> p_;
};

// Lets you pass any lambda (even capturing ones) as the Rust callback.
template <typename F>
void for_each(unsigned n, F&& f) {
    auto trampoline = [](unsigned i, void* ud) { (*static_cast<std::remove_reference_t<F>*>(ud))(i); };
    rs_for_each(n, trampoline, &f);
}

} // namespace rs
